--
-- Table structure for table `order_status_logs`
--

DROP TABLE IF EXISTS `order_status_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_status_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `old_status` varchar(30) DEFAULT NULL,
  `new_status` varchar(30) NOT NULL,
  `note` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_order_status_logs_new_status` (`new_status`),
  KEY `ix_order_status_logs_created_at` (`created_at`),
  KEY `ix_order_status_logs_order_id` (`order_id`),
  CONSTRAINT `order_status_logs_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`),
  CONSTRAINT `ck_order_status_logs_new_status` CHECK ((`new_status` in (_utf8mb4'PLACED',_utf8mb4'READY_TO_SHIP',_utf8mb4'SHIPPING',_utf8mb4'COMPLETED',_utf8mb4'DELIVERY_FAILED',_utf8mb4'CANCELLED'))),
  CONSTRAINT `ck_order_status_logs_old_status` CHECK (((`old_status` is null) or (`old_status` in (_utf8mb4'PLACED',_utf8mb4'READY_TO_SHIP',_utf8mb4'SHIPPING',_utf8mb4'COMPLETED',_utf8mb4'DELIVERY_FAILED',_utf8mb4'CANCELLED'))))
) ENGINE=InnoDB AUTO_INCREMENT=599 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

