--
-- Table structure for table `payments`
--

DROP TABLE IF EXISTS `payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `public_id` char(36) NOT NULL,
  `payment_code` varchar(50) NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `payment_method` varchar(50) NOT NULL,
  `payment_gateway` varchar(50) DEFAULT NULL,
  `payment_status` varchar(30) NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `transaction_code` varchar(100) DEFAULT NULL,
  `gateway_response` json DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  `paid_at` datetime DEFAULT NULL,
  `failed_at` datetime DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `public_id` (`public_id`),
  UNIQUE KEY `payment_code` (`payment_code`),
  UNIQUE KEY `transaction_code` (`transaction_code`),
  KEY `ix_payments_user_id` (`user_id`),
  KEY `ix_payments_payment_method` (`payment_method`),
  KEY `ix_payments_payment_status` (`payment_status`),
  KEY `ix_payments_created_at` (`created_at`),
  CONSTRAINT `payments_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_payments_amount` CHECK ((`amount` >= 0)),
  CONSTRAINT `ck_payments_payment_method` CHECK ((`payment_method` in (_utf8mb4'BANK',_utf8mb4'MOMO',_utf8mb4'CREDIT_CARD',_utf8mb4'MOCK',_utf8mb4'VNPAY'))),
  CONSTRAINT `ck_payments_payment_status` CHECK ((`payment_status` in (_utf8mb4'PENDING',_utf8mb4'PAID',_utf8mb4'FAILED',_utf8mb4'CANCELLED',_utf8mb4'REFUND_PENDING',_utf8mb4'REFUNDED')))
) ENGINE=InnoDB AUTO_INCREMENT=541 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

