--
-- Table structure for table `product_variants`
--

DROP TABLE IF EXISTS `product_variants`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_variants` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `public_id` char(36) NOT NULL,
  `product_id` bigint unsigned NOT NULL,
  `sku` varchar(255) NOT NULL,
  `variant_name` varchar(150) NOT NULL,
  `price` decimal(12,2) NOT NULL,
  `sale_price` decimal(12,2) DEFAULT NULL,
  `sale_start_at` datetime DEFAULT NULL,
  `sale_end_at` datetime DEFAULT NULL,
  `image_url` varchar(500) DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'ACTIVE',
  `tier_index` json DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `public_id` (`public_id`),
  KEY `ix_product_variants_price` (`price`),
  KEY `ix_product_variants_sale_price` (`sale_price`),
  KEY `ix_product_variants_status` (`status`),
  KEY `ix_product_variants_sku` (`sku`),
  KEY `ix_product_variants_product_id` (`product_id`),
  CONSTRAINT `product_variants_ibfk_1` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`),
  CONSTRAINT `ck_product_variants_price` CHECK ((`price` >= 0)),
  CONSTRAINT `ck_product_variants_sale_price` CHECK (((`sale_price` is null) or (`sale_price` >= 0))),
  CONSTRAINT `ck_product_variants_status` CHECK ((`status` in (_utf8mb4'ACTIVE',_utf8mb4'HIDDEN',_utf8mb4'OUT_OF_STOCK',_utf8mb4'DELETED')))
) ENGINE=InnoDB AUTO_INCREMENT=552 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

