--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `public_id` char(36) NOT NULL,
  `seller_id` bigint unsigned NOT NULL,
  `name` varchar(255) NOT NULL,
  `slug` varchar(280) NOT NULL,
  `short_description` varchar(500) DEFAULT NULL,
  `description` text,
  `brand` varchar(120) DEFAULT NULL,
  `origin` varchar(120) DEFAULT NULL,
  `warranty_info` varchar(255) DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'ACTIVE',
  `average_rating` decimal(3,2) NOT NULL DEFAULT (0.00),
  `review_count` int unsigned NOT NULL DEFAULT '0',
  `sold_count` int unsigned NOT NULL DEFAULT '0',
  `variant_options` json DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_products_seller_id_slug` (`seller_id`,`slug`),
  UNIQUE KEY `public_id` (`public_id`),
  KEY `ix_products_status` (`status`),
  KEY `ix_products_seller_id` (`seller_id`),
  KEY `ix_products_created_at` (`created_at`),
  KEY `ix_products_sold_count` (`sold_count`),
  KEY `ix_products_average_rating` (`average_rating`),
  FULLTEXT KEY `ix_products_fulltext_search` (`name`,`short_description`,`description`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`seller_id`) REFERENCES `seller_profiles` (`id`),
  CONSTRAINT `ck_products_average_rating_max` CHECK ((`average_rating` <= 5)),
  CONSTRAINT `ck_products_average_rating_min` CHECK ((`average_rating` >= 0)),
  CONSTRAINT `ck_products_review_count` CHECK ((`review_count` >= 0)),
  CONSTRAINT `ck_products_sold_count` CHECK ((`sold_count` >= 0)),
  CONSTRAINT `ck_products_status` CHECK ((`status` in (_utf8mb4'ACTIVE',_utf8mb4'HIDDEN',_utf8mb4'OUT_OF_STOCK',_utf8mb4'DELETED')))
) ENGINE=InnoDB AUTO_INCREMENT=254 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `products`
--

LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (1,'p0000001-0000-4000-8000-000000000000',1,'Tai Nghe Bluetooth Chống Ồn Wireless Pro X','tai-nghe-bluetooth-chong-on-wireless-pro-x','Tai nghe Bluetooth chống ồn chủ động (ANC) tiên tiến, chất âm Hi-Res chân thực, thời lượng pin đến 30h liên tục.','Tai Nghe Bluetooth Chống Ồn Wireless Pro X là dòng sản phẩm tai nghe không dây cao cấp dành cho tín đồ âm nhạc và công việc bận rộn.\n\n• Công nghệ chống ồn ANC chủ động: Loại bỏ đến 98% tiếng ồn môi trường xung quanh, giúp bạn tập trung tối đa khi làm việc hay thưởng thức âm nhạc đỉnh cao.\n• Âm thanh Hi-Res Audio: Màng loa 40mm tinh chỉnh chuyên nghiệp mang lại dải bass trầm sâu lắng, mid ngọt ngào và treble trong trẻo.\n• Đàm thoại rõ nét: Tích hợp micro đôi với công nghệ lọc nhiễu AI, bắt trọn giọng nói kể cả ở nơi đông người.\n• Kết nối Bluetooth 5.3: Đảm bảo đường truyền siêu ổn định, độ trễ cực thấp phù hợp cả cho việc xem phim và chơi game.\n• Thời lượng pin ấn tượng: Sử dụng liên tục lên đến 30 giờ khi bật ANC, hỗ trợ sạc nhanh 10 phút cho 3 giờ nghe nhạc.','DareU','Trung Quốc','24 tháng','ACTIVE',4.00,11,21,'[]',NULL,'2023-01-15 10:00:00','2026-08-09 04:55:39'),(2,'p0000002-0000-4000-8000-000000000000',1,'Bàn Phím Cơ Cơ Học RGB Gaming K87','ban-phim-co-co-hoc-rgb-gaming-k87','Bàn phím cơ Gaming K87 bố cục 87 phím gọn gàng, hệ thống đèn RGB 16.8 triệu màu linh hoạt và switch cơ học siêu bền.','Bàn Phím Cơ Cơ Học RGB Gaming K87 là lựa chọn hoàn hảo cho các gamer chuyên nghiệp và nhân viên văn phòng yêu thích trải nghiệm gõ phím chân thực.\n\n• Layout 87 key TKL gọn gàng: Tiết kiệm không gian bàn làm việc, dễ dàng bỏ vào balo di chuyển.\n• Switch cơ học độ bền 50 triệu lần nhấn: Mang lại phản hồi lực gõ cực chuẩn, tiếng gõ đầm tay và chính xác tuyệt đối.\n• Đèn LED RGB 16.8 triệu màu: Nhiều chế độ hiệu ứng chuyển màu sống động, dễ dàng chỉnh độ sáng và tốc độ chuyển hiệu ứng.\n• Keycap PBT/ABS cao cấp: Chống bám vân tay, nét in xuyên LED rõ ràng không lo phai mờ theo thời gian.\n• Tương thích đa nền tảng: Kết nối dễ dàng qua cổng USB chống nhiễu với Windows, MacOS và Android.','Local Brand VN','Việt Nam','Đổi trả 30 ngày','ACTIVE',4.67,3,4,'[{\"name\": \"Phân loại\", \"values\": [\"Tiêu chuẩn\", \"Nâng cấp\"]}]',NULL,'2023-01-15 10:00:00',NULL),(3,'p0000003-0000-4000-8000-000000000000',2,'Áo Sơ Mi Nam Form Rộng Unisex Style Hàn Quốc','ao-so-mi-nam-form-rong-unisex-style-han-quoc','Áo sơ mi nam form rộng phong cách Hàn Quốc trẻ trung, chất liệu cotton lụa mềm mịn, thoáng mát và chống nhăn hiệu quả.','Áo Sơ Mi Nam Form Rộng Unisex Style Hàn Quốc mang lại vẻ ngoài lịch lãm, hiện đại nhưng không kém phần thoải mái năng động.\n\n• Thiết kế Form Rộng Unisex: Chuẩn phong cách Streetwear Hàn Quốc, dễ dàng kết hợp với quần jeans, quần tây hay quần short.\n• Chất liệu lụa Cotton cao cấp: Bề mặt vải mềm mại, thấm hút mồ hôi tốt, mát mịn khi tiếp xúc với da.\n• Đường may tỉ mỉ: Khuy áo đơm chắc chắn, cổ áo cứng cáp giữ form sau nhiều lần giặt.\n• Dễ phối đồ: Thích hợp mặc đi học, đi làm, đi chơi hay đi tiệc nhẹ nhàng.\n• Bảo quản dễ dàng: Giặt máy chế độ nhẹ, giữ màu tốt và ít nhăn.','K-Beauty Lab','Hàn Quốc','Hạn sử dụng 24 tháng','ACTIVE',4.33,15,24,'[]',NULL,'2023-01-15 10:00:00','2026-08-09 04:55:39'),(4,'p0000004-0000-4000-8000-000000000000',2,'Quần Jeans Nam Ống Rộng Wide Leg Denim','quan-jeans-nam-ong-rong-wide-leg-denim','Quần Jeans nam ống rộng dáng Wide Leg Denim cá tính, chất vải bò dày dặn, bền màu và tạo form cực chuẩn.','Quần Jeans Nam Ống Rộng Wide Leg Denim là item thời trang không thể thiếu trong tủ đồ của các bạn trẻ yêu thích sự tự do, phong cách.\n\n• Dáng quần Wide Leg quyến rũ: Giúp che khuyết điểm chân, tôn dáng người mặc và tạo cảm giác thoải mái khi vận động.\n• Vải Denim Cotton 100%: Dày dặn, đầm tay, xử lý wash màu tự nhiên bền đẹp không bị phai màu nhiều khi giặt.\n• Khóa kéo kim loại chắc chắn: Khuy cài cao cấp, đường chỉ diễu kép gia cố ở các vị trí chịu lực.\n• Phong cách ứng dụng cao: Phối đồ linh hoạt với áo thun, áo sơ mi hay áo hoodie trẻ trung.','Sunhouse','Việt Nam','24 tháng','ACTIVE',4.11,9,15,'[{\"name\": \"Phân loại\", \"values\": [\"Tiêu chuẩn\", \"Nâng cấp\"]}]',NULL,'2023-01-15 10:00:00','2026-08-09 04:55:39'),(5,'p0000005-0000-4000-8000-000000000000',3,'Serum Dưỡng Sáng Đều Màu Da Vitamin C 15%','serum-duong-sang-deu-mau-da-vitamin-c-15','Serum Vitamin C 15% dưỡng sáng da, mờ thâm mụn, đều màu da và hỗ trợ chống oxy hóa mạnh mẽ.','Serum Dưỡng Sáng Đều Màu Da Vitamin C 15% là giải pháp chăm sóc da chuyên sâu giúp khôi phục vẻ rạng rỡ tươi trẻ cho làn da.\n\n• Nồng độ Vitamin C 15% ổn định: Thấm sâu vào biểu bì, ức chế sự hình thành hắc tố melanin, làm mờ nhanh các vết thâm sau mụn và đốm nâu.\n• Tăng cường Collagen: Hỗ trợ tái tạo tế bào da mới, cải thiện độ đàn hồi và làm mờ nếp nhăn nhỏ.\n• Bổ sung Hyaluronic Acid: Giúp cấp ẩm mịn màng, cân bằng độ ẩm tức thì cho da.\n• Kết cấu mỏng nhẹ: Thấm nhanh không gây bết dính hay bí tắc lỗ chân lông.\n• Thích hợp cho mọi loại da: Đặc biệt là làn da xỉn màu, da có nhiều vết thâm và có dấu hiệu lão hóa sớm.','Bobby','Việt Nam','Hạn sử dụng 36 tháng','ACTIVE',4.00,11,17,'[]',NULL,'2023-01-15 10:00:00',NULL),(6,'p0000006-0000-4000-8000-000000000000',4,'Nồi Chiên Không Dầu Điện Tử 6.5L Sunhouse','noi-chien-khong-dau-dien-tu-65l-sunhouse','Nồi chiên không dầu điện tử 6.5L Sunhouse công nghệ Rapid Air chiên nướng giòn ngon, giảm 85% lượng dầu mỡ thừa.','Nồi Chiên Không Dầu Điện Tử 6.5L Sunhouse mang đến giải pháp nấu nướng tiện lợi, an toàn cho sức khỏe cả gia đình.\n\n• Dung tích lớn 6.5L: Thoải mái chiên nguyên con gà 2kg hoặc chế biến lượng thực phẩm lớn cho gia đình 4-6 người.\n• Công nghệ nướng đối lưu Rapid Air: Luồng khí nóng tuần hoàn 360 độ giúp thực phẩm chín đều từ trong ra ngoài.\n• Bảng điều khiển cảm ứng thông minh: Tích hợp sẵn 8 chế độ nấu tự động cho khoai tây, sườn, tôm, bánh, gà...\n• Lòng nồi chống dính cao cấp: Dễ dàng tháo rời và vệ sinh sạch sẽ sau khi dùng.\n• Thân vỏ cách nhiệt an toàn: Thiết kế hiện đại, tinh tế làm nổi bật không gian bếp gia đình.','ProFit','Đài Loan','6 tháng','ACTIVE',4.14,14,21,'[{\"name\": \"Phân loại\", \"values\": [\"Tiêu chuẩn\", \"Nâng cấp\"]}]',NULL,'2023-01-15 10:00:00','2026-08-09 04:55:39'),(7,'p0000007-0000-4000-8000-000000000000',5,'Tã Bỉm Dán/Quần Cao Cấp Ultra Soft Cho Bé','ta-bim-dan-quan-cao-cap-ultra-soft-cho-be','Tã bỉm dán/quần cao cấp Ultra Soft siêu mỏng nhẹ, khả năng thấm hút vượt trội chống tràn 12h cho bé ngủ ngon.','Tã Bỉm Dán/Quần Cao Cấp Ultra Soft Cho Bé được thiết kế chuyên biệt nhằm chăm sóc làn da nhạy cảm nhất của trẻ nhỏ.\n\n• Chất liệu màng thở Ultra Soft: Siêu mềm mại như bông, không gây hằn đỏ hay kích ứng da bé.\n• Công nghệ lõi thấm hạt SAP Nhật Bản: Thấm hút tức thì lên tới 1000ml chất lỏng, khóa chặt độ ẩm không lo thấm ngược.\n• Độ mỏng chỉ 2mm: Cho bé tự do lật lẫy, bò chạy mà không gây vướng víu khó chịu.\n• Đai hông co giãn 360 độ: Vừa vặn ôm sát cơ thể bé, chống tràn hiệu quả suốt đêm dài.','NXB Trẻ','Việt Nam','Đổi trả nếu lỗi in','ACTIVE',4.75,8,15,'[]',NULL,'2023-01-15 10:00:00','2026-08-09 04:55:39'),(8,'p0000008-0000-4000-8000-000000000000',4,'Bộ Nồi Inox 3 Đáy Nắp Kính Cao Cấp KitchenArt','bo-noi-inox-3-day-nap-kinh-cao-cap-kitchenart','Bộ nồi Inox 3 đáy nắp kính cao cấp KitchenArt truyền nhiệt nhanh, giữ nhiệt lâu, dùng tốt trên mọi loại bếp.','Bộ Nồi Inox 3 Đáy Nắp Kính Cao Cấp KitchenArt là trợ thủ đắc lực giúp người nội trợ nấu ra những bữa ăn thơm ngon bồi bổ gia đình.\n\n• Đáy 3 lớp đúc nguyên khối: Lớp inox 304 an toàn thực phẩm, lớp nhôm nguyên chất truyền nhiệt cực nhanh và lớp inox 430 bắt từ nhạy bén.\n• Nắp kính cường lực chịu nhiệt: Trong suốt giúp dễ dàng quan sát món ăn đang nấu mà không cần mở nắp.\n• Quai cầm tán đinh chắc chắn: Cách nhiệt an toàn, di chuyển nồi thuận tiện.\n• Đa năng sử dụng: Phù hợp cho bếp từ, bếp hồng ngoại, bếp gas và máy rửa bát.','Xiaomi','Trung Quốc','18 tháng','ACTIVE',4.31,13,27,'[{\"name\": \"Phân loại\", \"values\": [\"Tiêu chuẩn\", \"Nâng cấp\"]}]',NULL,'2023-01-15 10:00:00','2026-08-09 04:55:39'),(9,'p0000009-0000-4000-8000-000000000000',6,'Thảm Tập Yoga TPE 2 Lớp Chống Trượt 8mm','tham-tap-yoga-tpe-2-lop-chong-truot-8mm','Thảm tập Yoga TPE 2 lớp chống trượt độ dày 8mm êm ái, độ bám sàn tuyệt đối bảo vệ tối đa đĩa đệm và khớp.','Thảm Tập Yoga TPE 2 Lớp Chống Trượt 8mm được sản xuất từ chất liệu cao su TPE sinh thái cao cấp an toàn cho sức khỏe người tập.\n\n• Cấu trúc 2 lớp dập nổi: Mặt trên vân chìm bám tay chân chống trơn trượt hiệu quả, mặt dưới dạng sóng bám chặt sàn nhà.\n• Độ dày 8mm chuẩn khung tập: Giảm chấn và chịu lực tốt, bảo vệ đầu gối, cùi chỏ và cột sống khi thực hiện các tư thế nâng cao.\n• Không mùi độc hại: Dễ dàng lau chùi vệ sinh sau khi tập, chống thấm mồ hôi.\n• Tặng kèm dây buộc và túi đeo: Tiện lợi mang theo đến phòng tập hay đi dã ngoại.','Ecovacs','Trung Quốc','24 tháng','ACTIVE',4.45,11,14,'[]',NULL,'2023-01-15 10:00:00',NULL),(10,'p0000010-0000-4000-8000-000000000000',7,'Sách Đắc Nhân Tâm - Dale Carnegie (Bìa Mềm)','sach-dac-nhan-tam-dale-carnegie-bia-mem','Sách Đắc Nhân Tâm của Dale Carnegie - cuốn sách bán chạy mọi thời đại về nghệ thuật giao tiếp và ứng xử con người.','Sách Đắc Nhân Tâm - Dale Carnegie (Bìa Mềm) là kiệt tác nghệ thuật sống và chìa khóa dẫn đến thành công trong công việc lẫn cuộc sống.\n\n• Nội dung sâu sắc, thực tế: Cung cấp những bài học vô giá về nguyên tắc thu phục lòng người, tạo dựng mối quan hệ bền vững.\n• Văn phong lôi cuốn: Dịch thuật chuẩn xác, dễ đọc, dễ hiểu và dễ áp dụng vào thực tế hàng ngày.\n• Chất lượng in ấn cao cấp: Giấy in chống lóa mắt, bìa mềm thiết kế trang nhã bọc dán chắc chắn.','Kingstyle','Việt Nam','12 tháng','ACTIVE',4.50,4,8,'[{\"name\": \"Phân loại\", \"values\": [\"Tiêu chuẩn\", \"Nâng cấp\"]}]',NULL,'2023-01-15 10:00:00','2026-08-09 04:55:39'),(11,'p0000011-0000-4000-8000-000000000000',8,'Hạt Hạnh Nhân Sấy Giòn Nguyên Vị Organic 500g','hat-hanh-nhan-say-gion-nguyen-vi-organic-500g','Hạt hạnh nhân sấy giòn nguyên vị Organic 500g nhập khẩu thơm ngon, giàu dinh dưỡng và Omega 3 tốt cho sức khỏe.','Hạt Hạnh Nhân Sấy Giòn Nguyên Vị Organic 500g được tuyển chọn từ những hạt hạnh nhân to tròn, chất lượng nhất.\n\n• 100% Organic tự nhiên: Không chứa chất bảo quản, không thêm đường hay phụ gia độc hại.\n• Giá trị dinh dưỡng cao: Giàu vitamin E, Magie, chất xơ và chất béo lành mạnh giúp cải thiện sức khỏe tim mạch và duy trì vóc dáng.\n• Quy trình sấy bơ giòn rụm: Giữ trọn vẹn hương vị bùi béo tự nhiên đặc trưng của hạnh nhân.\n• Đóng gói hũ nắp nhôm kín: Đảm bảo độ giòn thơm lâu dài, thích hợp làm món ăn vặt lành mạnh mỗi ngày.','VietGAP','Việt Nam','Hạn sử dụng 12 tháng','ACTIVE',4.00,3,5,'[]',NULL,'2023-01-15 10:00:00','2026-08-09 04:55:39'),(12,'p0000012-0000-4000-8000-000000000000',9,'Loa Bluetooth Kháng Nước SoundMaster Boom X','loa-bluetooth-khang-nuoc-soundmaster-boom-x','Loa Bluetooth SoundMaster Boom X công suất mạnh mẽ, chuẩn kháng nước IPX7, âm bass uy lực cho tiệc tùng bùng nổ.','Loa Bluetooth Kháng Nước SoundMaster Boom X mang lại trải nghiệm âm thanh di động đỉnh cao cho những chuyến dã ngoại hay tiệc hồ bơi.\n\n• Công suất RMS 30W: Loa kéo đôi công nghệ Bass Radiator cho dải âm trầm mạnh mẽ, không bị rè khi mở âm lượng tối đa.\n• Chuẩn chống nước IPX7: An tâm sử dụng dưới trời mưa hay ngâm mình trong nước ở độ sâu 1m trong 30 phút.\n• Kết nối Bluetooth 5.2: Tầm xa lên tới 15m, kết nối 2 loa cùng lúc tạo không gian âm thanh Stereo ấn tượng.\n• Pin dung lượng lớn 5200mAh: Phát nhạc liên tục đến 15 giờ chỉ với một lần sạc đầy.','NoiThat365','Việt Nam','24 tháng','ACTIVE',4.60,5,8,'[{\"name\": \"Phân loại\", \"values\": [\"Tiêu chuẩn\", \"Nâng cấp\"]}]',NULL,'2023-01-15 10:00:00','2026-08-09 04:55:39'),(13,'p0000013-0000-4000-8000-000000000000',10,'Đồng Hồ Nam Dây Da Thật Chronograph WatchFlex','dong-ho-nam-day-da-that-chronograph-watchflex','Đồng hồ nam dây da thật Chronograph WatchFlex thiết kế 6 kim thể thao sang trọng, máy Quartz Nhật Bản chính xác.','Đồng Hồ Nam Dây Da Thật Chronograph WatchFlex là phụ kiện thể hiện đẳng cấp và bản lĩnh phong thái của người đàn ông thành đạt.\n\n• Mặt kính Mineral Crystal cường lực: Chống xước hiệu quả, hiển thị sắc nét dưới ánh nắng mặt trời.\n• Dây da bò thật cao cấp: Mềm mại ôm sát cổ tay, thoáng khí không gây hôi tay khi đeo cả ngày.\n• Bộ máy Chronograph thể thao: Tích hợp 3 mặt số phụ bấm giờ thể thao chính xác và lịch ngày tiện lợi.\n• Kháng nước 5ATM: Thoải mái đi mưa, rửa tay hay tắm rửa hàng ngày.','Ugreen','Trung Quốc','12 tháng','ACTIVE',3.77,13,19,'[]',NULL,'2023-01-15 10:00:00','2026-08-09 04:55:39'),(14,'p0000014-0000-4000-8000-000000000000',12,'Thức Ăn Hạt Khô Cho Mèo Royal Canin 2kg','thuc-an-hat-kho-cho-meo-royal-canin-2kg','Thức ăn hạt khô cho mèo Royal Canin 2kg công thức dinh dưỡng cân bằng giúp lông bóng mượt và hỗ trợ hệ tiêu hóa.','Thức Ăn Hạt Khô Cho Mèo Royal Canin 2kg được nghiên cứu phát triển bởi các chuyên gia dinh dưỡng thú cưng hàng đầu.\n\n• Thành phần đạm động vật cao cấp: Cung cấp đầy đủ Taurine và axit amin thiết yếu hỗ trợ thị lực và cơ bắp phát triển khỏe mạnh.\n• Tăng cường Omega 3 & 6: Giúp da khỏe mạnh, giảm rụng lông và cho bộ lông mềm mượt.\n• Công thức tiêu búi lông (Hairball Care): Giúp đào thải lông trong dạ dày mèo ra ngoài tự nhiên qua đường tiêu hóa.\n• Kích thước hạt phù hợp: Giúp mèo dễ bốc lượm và tạo lực nhai hỗ trợ làm sạch răng miệng.','LEGO','Đan Mạch','Đổi trả 7 ngày','ACTIVE',4.28,18,34,'[{\"name\": \"Phân loại\", \"values\": [\"Tiêu chuẩn\", \"Nâng cấp\"]}]',NULL,'2023-01-15 10:00:00','2026-08-09 04:55:39'),(15,'p0000015-0000-4000-8000-000000000000',1,'Sạc Dự Phòng Fast Charge 20000mAh 22.5W','sac-du-phong-fast-charge-20000mah-225w','Sạc dự phòng Fast Charge 20000mAh 22.5W sạc nhanh đa thiết bị, màn hình LED hiển thị % pin chuẩn xác.','Sạc Dự Phòng Fast Charge 20000mAh 22.5W là người bạn đồng hành không thể thiếu cho những chuyến đi xa hay công tác dài ngày.\n\n• Dung lượng thực 20000mAh: Sạc đầy iPhone 14 khoảng 4-5 lần, đảm bảo năng lượng cả ngày dài.\n• Hỗ trợ